// Which request actually carried the token? httpbin tells us.
// Run all three nodes and compare: A and C authenticate, B does not hit /bearer at all.
return $input.all().map(item => ({
  json: {
    authenticated: item.json.authenticated ?? item.json.body?.authenticated ?? null,
    seenByServer: item.json.args ?? item.json.body?.args ?? null,
    statusCode: item.json.statusCode ?? null
  }
}));
